-- Targets anchor to matching main or optional quest instructions.
-- Only its preloaded macros and secure binding proxies execute during combat.
APR.RaidIconButtons = { buttons = {}, pool = {}, targets = {} }
local Rail = APR.RaidIconButtons
APR.currentStep.raidIconButtons = Rail.buttons

local function ShowTargetTooltip(button)
    GameTooltip:SetOwner(button, "ANCHOR_BOTTOM")
    APR:AddTooltipLine(GameTooltip, TARGET, "currentStep", "accent")
    APR:AddTooltipLine(GameTooltip, APR:GetRaidIconNpcName(button.npcID) or tostring(button.npcID),
        "currentStep", "base", true)
    GameTooltip:Show()
end--[[APR_DIAG]]; ShowTargetTooltip = APRTrace("APR-Core/ui/route/RaidIconButtons.lua:12:ShowTargetTooltip#1", ShowTargetTooltip)--[[/APR_DIAG]]

local function HideTargetTooltip() GameTooltip:Hide() end--[[APR_DIAG]]; HideTargetTooltip = APRTrace("APR-Core/ui/route/RaidIconButtons.lua:20:HideTargetTooltip#2", HideTargetTooltip)--[[/APR_DIAG]]

local function SetAttribute(button, key, value)
    if button:GetAttribute(key) ~= value then button:SetAttribute(key, value) end
end--[[APR_DIAG]]; SetAttribute = APRTrace("APR-Core/ui/route/RaidIconButtons.lua:22:SetAttribute#3", SetAttribute)--[[/APR_DIAG]]

function Rail:RefreshMacros()
    if not self.buttons[1] then self.pendingMacros = nil; return end
    if InCombatLockdown() then self.pendingMacros = true return end
    self.pendingMacros = nil
    local all = APR:BuildRaidIconMacro(self.targets, nil, self.markerIndices)
    for index, button in ipairs(self.buttons) do
        local macro = APR:BuildRaidIconMacro(button.npcID, nil, button.targetIndex)
        SetAttribute(button, "macrotext", macro)
        SetAttribute(button, "apr-target-all-macro", all)
        SetAttribute(button, "type1", macro ~= "" and "macro" or nil)
    end
end--[[APR_DIAG]]; Rail.RefreshMacros = APRTrace("APR-Core/ui/route/RaidIconButtons.lua:26:Rail:RefreshMacros#4", Rail.RefreshMacros)--[[/APR_DIAG]]

local function AcquireButton(index, parent)
    local button = Rail.pool[index]
    if not button then
        button = CreateFrame("Button", nil, parent, "SecureActionButtonTemplate,BackdropTemplate")
        button:SetSize(APR.currentStep.layout.actionButtonSize, APR.currentStep.layout.actionButtonSize)
        button:SetNormalTexture("Interface\\TargetingFrame\\UI-RaidTargetingIcon_8")
        button:SetHighlightTexture("Interface\\Buttons\\UI-Common-MouseHilight")
        button:RegisterForClicks("AnyUp", "AnyDown")
        button:SetScript("OnEnter", ShowTargetTooltip)
        button:SetScript("OnLeave", HideTargetTooltip)
        if APR.RegisterSkinTarget then
            APR:RegisterSkinTarget(button, "icon", { texture = button:GetNormalTexture(), fullTexture = true })
        end
        Rail.pool[index] = button
    elseif button:GetParent() ~= parent then
        button:SetParent(parent)
    end
    return button
end--[[APR_DIAG]]; AcquireButton = APRTrace("APR-Core/ui/route/RaidIconButtons.lua:38:AcquireButton#5", AcquireButton)--[[/APR_DIAG]]

-- Use the same stable key ordering as CurrentStepRows.
local function VisibleRows(list, fillers)
    local keys, rows = {}, {}
    for key, row in pairs(list or {}) do
        if not row.stale and not row.hiddenInCombat then keys[#keys + 1] = key end
    end
    table.sort(keys, --[[APR_DIAG]]APRTrace("APR-Core/ui/route/RaidIconButtons.lua:64:callback#7", --[[/APR_DIAG]]function(a, b)
        if fillers then
            local left, right = list[a], list[b]
            local leftID, rightID = tonumber(left.questID), tonumber(right.questID)
            if leftID and rightID and leftID ~= rightID then return leftID < rightID end
            if tostring(left.questID) ~= tostring(right.questID) then return tostring(left.questID) < tostring(right.questID) end
            local leftIndex, rightIndex = tonumber(left.objectiveIndex) or 0, tonumber(right.objectiveIndex) or 0
            if leftIndex ~= rightIndex then return leftIndex < rightIndex end
        end
        return tostring(a) < tostring(b)
    end--[[APR_DIAG]])--[[/APR_DIAG]])
    for _, key in ipairs(keys) do rows[#rows + 1] = list[key] end
    return rows
end--[[APR_DIAG]]; VisibleRows = APRTrace("APR-Core/ui/route/RaidIconButtons.lua:59:VisibleRows#6", VisibleRows)--[[/APR_DIAG]]

local function ResolveHost(id, rows, extras, objectives)
    local binding = (APR.currentStep.raidIconQuestBindings or {})[id]
        or (APR.currentStep.raidIconInferredBindings or {})[id]
    if binding then
        for _, row in ipairs(rows) do
            if row.questID == binding.questID and
                (not binding.objectiveIndex or tonumber(row.objectiveIndex) == binding.objectiveIndex) then return row end
        end
        return false -- An explicit objective that vanished must never fall back to another row.
    else
        local name, localized = APR:GetRaidIconNpcName(id)
        local match
        if localized and type(name) == "string" and name ~= "" then
            for _, row in ipairs(rows) do
                if type(row.questID) == "number" and tonumber(row.objectiveIndex) and not row.isScenario then
                    local data = objectives[row.questID]
                    if data == nil then
                        data = C_QuestLog and C_QuestLog.GetQuestObjectives and C_QuestLog.GetQuestObjectives(row.questID) or false
                        objectives[row.questID] = data
                    end
                    local objective = APRSecret:CanAccessTable(data) and data[tonumber(row.objectiveIndex)]
                    if APRSecret:CanAccessTable(objective) and APRSecret:CanAccessValue(objective.type) and objective.type == "monster" and
                        APRSecret:CanAccessValue(objective.text) and type(objective.text) == "string" and
                        objective.text:find(name, 1, true) then
                        if match then return rows[1] end -- Ambiguous names cannot prove ownership.
                        match = row
                    end
                end
            end
        end
        if match then
            APR.currentStep.raidIconInferredBindings = APR.currentStep.raidIconInferredBindings or {}
            APR.currentStep.raidIconInferredBindings[id] = {
                questID = match.questID, objectiveIndex = tonumber(match.objectiveIndex),
            }
            return match
        end
    end
    return rows[1] or extras[#extras]
end--[[APR_DIAG]]; ResolveHost = APRTrace("APR-Core/ui/route/RaidIconButtons.lua:69:ResolveHost#8", ResolveHost)--[[/APR_DIAG]]

function Rail:Flush(deferHostLayout)
    if InCombatLockdown() then return end
    if not self.pendingTargets then
        if self.pendingMacros then self:RefreshMacros() end
        return
    end
    local targets = self.pendingTargets
    self.pendingTargets = nil
    local rows = VisibleRows(APR.currentStep.questsList)
    for _, row in ipairs(VisibleRows(APR.currentStep.fillersList, true)) do
        if row.rowKind == "filler" then rows[#rows + 1] = row end
    end
    local extras = VisibleRows(APR.currentStep.questsExtraTextList)
    local referenceAction
    for _, row in ipairs(rows) do
        if row.IconButton and row.IconButton:IsShown() then referenceAction = row.IconButton break end
    end
    local right = APR.settings.profile.currentStepQuestButtonPositionRight
    local gap = APR.currentStep.layout.actionButtonGap
    local previous, objectives, active = {}, {}, {}
    self.markerIndices = {}
    for targetIndex, id in ipairs(targets) do
        local host = ResolveHost(id, rows, extras, objectives)
        if host ~= false then
            active[#active + 1] = { id = id, host = host, targetIndex = targetIndex }
            self.markerIndices[id] = targetIndex
        end
    end
    targets = {}
    self.unhostedCount = 0
    for index, entry in ipairs(active) do
        local id, host, targetIndex = entry.id, entry.host, entry.targetIndex
        targets[index] = id
        if not host then self.unhostedCount = self.unhostedCount + 1 end
        local parent = host and host:GetParent() or APR.fillersFrame.StepHolder
        local button = AcquireButton(index, parent)
        local action = (host and host.IconButton) or referenceAction
        local width = action and action:GetWidth() or APR.currentStep.layout.actionButtonSize
        local height = action and action:GetHeight() or APR.currentStep.layout.actionButtonSize
        -- Main and optional panels can inherit different tracker/UI scales.
        local scale = action and action:GetEffectiveScale() / parent:GetEffectiveScale() or 1
        if button:GetScale() ~= scale then button:SetScale(scale) end
        if button:GetWidth() ~= width or button:GetHeight() ~= height then button:SetSize(width, height) end
        if button.markerIndex ~= targetIndex then
            button:SetNormalTexture(targetIndex <= 8 and ("Interface\\TargetingFrame\\UI-RaidTargetingIcon_" .. (9 - targetIndex))
                or "Interface\\Icons\\INV_Misc_QuestionMark")
            button:GetNormalTexture():SetAllPoints(button)
            button:GetNormalTexture():SetTexCoord(0, 1, 0, 1)
            button.markerIndex = targetIndex
        end
        local adjacent = previous[host or parent] or (host and host.IconButton and host.IconButton:IsShown() and host.IconButton)
        local point = right and "LEFT" or "RIGHT"
        if button.anchorHost ~= (host or parent) or button.anchorAdjacent ~= adjacent or button.railRight ~= right then
            button:ClearAllPoints()
            if adjacent then
                button:SetPoint(point, adjacent, right and "RIGHT" or "LEFT", right and gap or -gap, 0)
            else
                button:SetPoint(point, host or parent, right and "RIGHT" or "LEFT", right and gap or -gap, 0)
            end
        end
        button.anchorHost, button.anchorAdjacent = host or parent, adjacent
        previous[host or parent] = button
        button.npcID, button.questID, button.objectiveIndex = id, host and host.questID, host and host.objectiveIndex
        button.railRight, button.railParent, button.questHost = right, parent, host
        self.buttons[index] = button
        button.targetIndex = targetIndex
        SetAttribute(button, "apr-target-index", targetIndex)
        if not button:IsShown() then button:Show() end
    end
    for index = #self.buttons, #targets + 1, -1 do
        local button = self.buttons[index]
        button:Hide()
        SetAttribute(button, "type1", nil)
        SetAttribute(button, "macrotext", nil)
        SetAttribute(button, "apr-target-all-macro", nil)
        button.npcID, button.questID, button.objectiveIndex, button.questHost = nil, nil, nil, nil
        self.buttons[index] = nil
    end
    self.targets = targets
    APR.currentStep.raidIconButton = self.buttons[1]
    self:RefreshMacros()
    if APR.Gamepad then
        for index, button in ipairs(self.buttons) do
            APR.Gamepad:RegisterActionButton(button, string.format("raid-%05d", index), true, "target")
        end
        APR.Gamepad:SetTargetCycleTargets(table.concat(targets, ","))
    end
    if deferHostLayout then
        -- The completed content pass publishes filler geometry/visibility once.
        APR.fillersFrame.pendingRefresh = true
    elseif APR.fillersFrame.RefreshFillersFrame then
        APR.fillersFrame:RefreshFillersFrame(true)
    end
end--[[APR_DIAG]]; Rail.Flush = APRTrace("APR-Core/ui/route/RaidIconButtons.lua:100:Rail:Flush#9", Rail.Flush)--[[/APR_DIAG]]

function Rail:SetTargets(value, deferHostLayout)
    self.pendingTargets = APR:NormalizeRaidIconTargets(APR.settings.profile.currentStepShow and value or nil)
    self:Flush(deferHostLayout)
end--[[APR_DIAG]]; Rail.SetTargets = APRTrace("APR-Core/ui/route/RaidIconButtons.lua:158:Rail:SetTargets#10", Rail.SetTargets)--[[/APR_DIAG]]
